export function installMoneyDisplay(){
 const selector='input[data-money],.salary-grid input,.monthly-grid input[data-kind="amount"],.bank-grid input[data-field="amount"],.zkh-payment-grid input[data-field="amount"],.zkh-payment-grid input[data-field="commission"],input[data-reserve],input[data-extra-credit],input[data-family-initial]';
 function paint(input){const wrap=input.parentElement;if(!wrap?.classList.contains('money-display'))return;const value=input.value.trim().replace(/[\s₽]/g,'').replace(',','.');wrap.lastElementChild.textContent=value!==''&&Number.isFinite(Number(value))?Number(value).toLocaleString('ru-RU',{maximumFractionDigits:4})+' ₽':'';wrap.classList.toggle('money-empty',!wrap.lastElementChild.textContent);}
 function scan(){const inputs=new Set(document.querySelectorAll(selector));document.querySelectorAll('label input').forEach(e=>{if(e.closest('label').textContent.includes('₽')&&!['date','month','checkbox'].includes(e.type))inputs.add(e);});for(const input of inputs){if(input.closest('.money-display')){paint(input);continue;}if(['date','month','checkbox','file'].includes(input.type))continue;const wrap=document.createElement('span');wrap.className='money-display';input.before(wrap);wrap.append(input);const text=document.createElement('span');text.className='money-display-text';text.setAttribute('aria-hidden','true');wrap.append(text);paint(input);}}
 let queued=false;const schedule=()=>{if(queued)return;queued=true;queueMicrotask(()=>{queued=false;observer.disconnect();scan();observer.observe(document.body,{childList:true,subtree:true});});};const observer=new MutationObserver(schedule);observer.observe(document.body,{childList:true,subtree:true});document.addEventListener('input',e=>{if(e.target.matches('input'))paint(e.target);},true);document.addEventListener('focusout',e=>{if(e.target.matches('input'))paint(e.target);},true);document.addEventListener('click',schedule);scan();
}
